export const LOCALIZATION_EN = Object.freeze(Object.fromEntries(Object.keys(ID).map((key) => [key, key])));
export const LOCALIZATION_ID = Object.freeze({ ...ID });

export function getLocalizationParity() {
  const englishKeys = new Set(Object.keys(LOCALIZATION_EN));
  const indonesianKeys = new Set(Object.keys(LOCALIZATION_ID));
  return {
    missingEnglish: [...indonesianKeys].filter((key) => !englishKeys.has(key)),
    missingIndonesian: [...englishKeys].filter((key) => !indonesianKeys.has(key)),
  };
}

export function translateIndonesian(value) {
  if (value === null || value === undefined) return '';
  const source = String(value);
  const text = source.trim();
  const canonicalText = text.replace(/FRL\.(?=\d)/g, 'FRL');
  if (!text) return source;
  const monthNames = INDONESIAN_MONTH_NAMES;
  const calendar = text.match(/^Year (\d+) · ([A-Z][a-z]{2}) · Week ([1-4])$/);
  if (calendar) return source.replace(text, `Tahun ${calendar[1]} · ${monthNames[calendar[2]] ?? calendar[2]} · Minggu ${calendar[3]}`);
  const shortCalendar = text.match(/^([A-Z][a-z]{2}) · W([1-4])$/);
  if (shortCalendar) return source.replace(text, `${monthNames[shortCalendar[1]] ?? shortCalendar[1]} · M${shortCalendar[2]}`);
  const monthlySummary = text.match(/^Monthly summary · ([A-Z][a-z]{2})$/);
  if (monthlySummary) return source.replace(text, `Ringkasan bulanan · ${monthNames[monthlySummary[1]] ?? monthlySummary[1]}`);
  const deleteLabel = text.match(/^Delete (.+)$/);
  if (deleteLabel) return source.replace(text, `Hapus ${deleteLabel[1]}`);
  const birthday = text.match(/^Birthday ([A-Z][a-z]{2}) (\d{4})(?: · Age (\d+))?$/);
  if (birthday) return source.replace(text, `Ulang tahun ${monthNames[birthday[1]] ?? birthday[1]} ${birthday[2]}${birthday[3] ? ` · Usia ${birthday[3]}` : ''}`);
  if (monthNames[text]) return source.replace(text, monthNames[text]);
  const direct = ID[text] ?? ID[canonicalText];
  const normalizeGlossary = (localized) => String(localized)
    .replaceAll('$', 'FRL.')
    .replace(/FRL(?=\d)/g, 'FRL.')
    .replace(/Basis penggemar/gi, 'Jumlah Penggemar')
    .replace(/\bRoster\b/gi, 'Daftar Anggota')
    .replace(/\blineup\b/gi, 'susunan anggota')
    .replace(/\bOkupansi\b/gi, 'Keterisian')
    .replace(/Panggilan Video/gi, 'Video Call')
    .replace(/Temu Penggemar/gi, 'Meet & Greet');
  if (direct) return source.replace(text, normalizeGlossary(direct));
  for (const [pattern, replacement] of patterns) if (pattern.test(canonicalText)) {
    const localized = canonicalText.replace(pattern, replacement);
    return source.replace(text, normalizeGlossary(localized));
  }
  const embeddedCalendar = source
    .replace(/Year (\d+)\s*\xB7\s*([A-Z][a-z]{2})\s*\xB7\s*Week ([1-4])/g, (_, year, month, week) => indonesianCalendarDate(year, month, week))
    .replace(/Year (\d+),?\s*Month (\d+),?\s*Week (\d+)/g, (_, year, month, week) => {
      const monthKey = Object.keys(INDONESIAN_MONTH_NAMES)[Math.max(0, Math.min(11, Number(month) - 1))];
      return indonesianCalendarDate(year, monthKey, week);
    })
    .replace(/Year (\d+),?\s*Week (\d+)/g, (_, year, week) => indonesianCalendarFromWeek(year, week));
  return normalizeGlossary(embeddedCalendar);
}

const sources = new WeakMap();
const rendered = new WeakMap();
const attributes = ['aria-label', 'title', 'placeholder'];

function localizeNode(node, language) {
  if (node instanceof Element && node.closest('[data-i18n-ignore]')) return;
  if (node.nodeType === Node.TEXT_NODE && node.parentElement?.closest('[data-i18n-ignore]')) return;
  if (node.nodeType === Node.TEXT_NODE) {
    const current = node.nodeValue;
    if (rendered.get(node) !== current) sources.set(node, current);
    const source = sources.get(node) ?? current;
    // An <option> without an explicit value derives its submitted value from
    // its text. Preserve the original gameplay value before translating that
    // text (for example, Wed -> Rab), otherwise controlled selects can send a
    // localized label into engine APIs that require canonical IDs.
    if (node.parentElement?.tagName === 'OPTION' && !node.parentElement.hasAttribute('value')) {
      node.parentElement.setAttribute('value', source.trim());
    }
    const next = (language === 'id' ? translateIndonesian(source) : source).replace(/FRL(?=\d)/g, 'FRL.');
    rendered.set(node, next);
    if (current !== next) node.nodeValue = next;
    return;
  }
  if (!(node instanceof Element) || ['SCRIPT', 'STYLE'].includes(node.tagName)) return;
  for (const attribute of attributes) {
    if (!node.hasAttribute(attribute)) continue;
    const sourceAttribute = `data-i18n-source-${attribute}`;
    const source = node.getAttribute(sourceAttribute) ?? node.getAttribute(attribute);
    node.setAttribute(sourceAttribute, source);
    node.setAttribute(attribute, (language === 'id' ? translateIndonesian(source) : source).replace(/FRL(?=\d)/g, 'FRL.'));
  }
  node.childNodes.forEach((child) => localizeNode(child, language));
}

export function localizeDocument(language) {
  // Portaled modals are mounted under document.body, outside #root.
  // Observe body so confirmation, member, campaign, and perk dialogs localize too.
  const root = document.body;
  if (!root) return () => {};
  localizeNode(root, language);
  const observer = new MutationObserver((mutations) => mutations.forEach((mutation) => {
    if (mutation.type === 'characterData') localizeNode(mutation.target, language);
    else mutation.addedNodes.forEach((node) => localizeNode(node, language));
  }));
  observer.observe(root, { childList: true, subtree: true, characterData: true });
  return () => observer.disconnect();
}
